query:
-- Deletar squads que estão vazios (sem jogadores) para forçar recriação com jogadores corretos
DELETE FROM squads WHERE id IN (
  SELECT s.id FROM (
    SELECT s.id FROM squads s
    LEFT JOIN squadPlayers sp ON sp.squadId = s.id
    GROUP BY s.id
    HAVING COUNT(sp.id) = 0
  ) AS empty_squads
);

